export interface Shot {
  id: string;
  prompt: string;
  imageUrl?: string;
  base64?: string;
  mediaId?: string;
  mimeType?: string;
  isGenerating: boolean;
  parentMediaId?: string;
  placeholder?: string;
}

import React, { useRef } from 'react';
import { Shot } from '../types';

interface ShotTileProps {
  shot: Shot;
  isDragging: boolean;
  isDragTarget: boolean;
  showGrip: boolean;
  onUpdate: (id: string, updates: Partial<Shot>) => void;
  onGenerate: (id: string) => void;
  onDelete: (id: string) => void;
  onSave: (id: string) => void;
  saveState: 'idle' | 'saving' | 'saved';
  onFollowUp: (id: string) => void;
  onDragStart: (e: React.DragEvent, id: string) => void;
  onDragOver: (e: React.DragEvent, id: string) => void;
  onDragEnd: (e: React.DragEvent) => void;
}

export const ShotTile: React.FC<ShotTileProps> = ({
  shot,
  isDragging,
  isDragTarget,
  showGrip,
  onUpdate,
  onGenerate,
  onDelete,
  onSave,
  saveState,
  onFollowUp,
  onDragStart,
  onDragOver,
  onDragEnd,
}) => {
  const inputRef = useRef<HTMLTextAreaElement>(null);

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      if (canSubmit) {
        onGenerate(shot.id);
      }
    }
  };

  const isGenerating = shot.isGenerating;
  const hasGeneratedImage = !!(shot.imageUrl && shot.mediaId);
  const canSubmit = !isGenerating && !hasGeneratedImage && shot.prompt.trim().length > 0;

  const getSaveIcon = () => {
    if (saveState === 'saving') return 'sync';
    if (saveState === 'saved') return 'check_circle';
    return 'download';
  };

  const getSaveTitle = () => {
    if (saveState === 'saving') return 'Saving...';
    if (saveState === 'saved') return 'Saved to Gallery';
    return 'Save to Gallery';
  };

  return (
    <div
      draggable={showGrip}
      onDragStart={(e) => onDragStart(e, shot.id)}
      onDragOver={(e) => onDragOver(e, shot.id)}
      onDragEnd={onDragEnd}
      className={`relative group transition-all duration-200 flex flex-col ${
        isDragging ? 'opacity-40 scale-95' : 'opacity-100'
      } ${
        isDragTarget ? 'bg-white/5 ring-1 ring-[#969696] rounded-xl' : 'bg-transparent'
      }`}
    >
      {/* Media Preview Area */}
      <div className="relative aspect-video w-full overflow-hidden cursor-grab active:cursor-grabbing bg-black rounded-xl border border-[#595959]">
        {shot.imageUrl && (
          <img
            src={shot.imageUrl}
            alt={shot.prompt}
            draggable={false}
            className={`w-full h-full object-cover select-none pointer-events-none transition-opacity duration-300 ${isGenerating ? 'opacity-20' : 'opacity-100'}`}
          />
        )}

        {isGenerating && (
          <div className="absolute inset-0 flex items-center justify-center z-20">
            <span className="text-white text-2xl tracking-[0.2em] font-normal animate-pulse pb-2">
              ...
            </span>
          </div>
        )}
      </div>

      <div className="mt-3 flex flex-col gap-1.5">
        {/* Solid Prompt Input Box with Bottom-Right Arrow */}
        <div className="relative flex bg-black border border-[#595959] hover:border-[#7a7a7a] focus-within:border-[#969696] rounded-xl transition-colors overflow-hidden">
          <textarea
            ref={inputRef}
            value={shot.prompt}
            onChange={(e) => onUpdate(shot.id, { prompt: e.target.value })}
            onKeyDown={handleKeyDown}
            readOnly={hasGeneratedImage || isGenerating}
            placeholder={shot.placeholder || "Describe shot..."}
            className={`flex-1 bg-transparent text-[13px] font-medium leading-[1.6] resize-none focus:outline-none placeholder:text-[rgba(255,255,255,0.35)] scrollbar-hide pt-2.5 pb-[28px] pl-[10px] pr-8 min-h-[64px] max-h-[64px] overflow-y-auto text-white tracking-[0.1px] ${
              (hasGeneratedImage || isGenerating) ? 'opacity-60 cursor-default' : ''
            }`}
          />
          {!hasGeneratedImage && (
            <button
              onClick={() => onGenerate(shot.id)}
              disabled={!canSubmit}
              className="absolute right-1.5 bottom-1.5 p-1 text-[rgba(218,220,224,0.55)] hover:text-white disabled:opacity-0 transition-all cursor-pointer z-10 flex items-center justify-center"
              title="Generate Shot"
            >
              <span className="material-symbols-outlined text-[20px]">arrow_forward</span>
            </button>
          )}
        </div>

        {/* Action Buttons Row */}
        <div className="flex items-center justify-between h-8">
          {/* Left Actions */}
          <div className="flex items-center">
            {hasGeneratedImage && (
              <button
                onClick={() => onFollowUp(shot.id)}
                className="flex items-center gap-1.5 py-1.5 pr-1.5 text-[rgba(218,220,224,0.55)] hover:text-white transition-colors"
                title="Next shot"
              >
                <span className="material-symbols-outlined text-[18px]">tab_new_right</span>
                <span className="text-[11px] font-medium tracking-[0.1px]">Next shot</span>
              </button>
            )}
          </div>

          {/* Right Actions */}
          <div className="flex items-center gap-0.5">
            <button
              onClick={() => onSave(shot.id)}
              disabled={!hasGeneratedImage || saveState === 'saving'}
              className={`p-1.5 transition-colors disabled:opacity-20 disabled:pointer-events-none ${
                saveState === 'saving' ? 'text-white' : 
                saveState === 'saved' ? 'text-green-400' : 
                'text-[rgba(218,220,224,0.55)] hover:text-white'
              }`}
              title={getSaveTitle()}
            >
              <span className={`material-symbols-outlined text-[18px] ${saveState === 'saving' ? 'animate-spin' : ''}`}>
                {getSaveIcon()}
              </span>
            </button>

            <button
              onClick={() => onDelete(shot.id)}
              className="py-1.5 pl-1.5 text-[rgba(218,220,224,0.55)] hover:text-red-400 transition-colors"
              title="Delete Shot"
            >
              <span className="material-symbols-outlined text-[18px]">delete</span>
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

import React from 'react';

export const SectionLabel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div className="flex items-center px-2 mb-1.5">
    <span className="text-[11px] font-medium text-[rgba(218,220,224,0.9)] tracking-[0.1px] normal-case">
      {children}
    </span>
  </div>
);

interface PillButtonProps {
  icon?: React.ReactNode;
  children: React.ReactNode;
  variant?: 'filled' | 'outline' | 'solid';
  onClick?: () => void;
  className?: string;
  disabled?: boolean;
}

export const PillButton: React.FC<PillButtonProps> = ({ 
  icon, children, variant = 'filled', onClick, className = '', disabled 
}) => {
  const base = 'flex items-center gap-[2px] justify-center h-[34px] rounded-xl font-medium tracking-[0.1px] transition-all cursor-pointer disabled:opacity-40 disabled:cursor-not-allowed';
  const variants: Record<string, string> = {
    filled: 'bg-[#969696] hover:bg-[#a6a6a6] active:bg-[#868686] text-black text-[11px] pl-[8px] pr-[24px] py-1 select-none',
    outline: 'border border-[#595959] hover:bg-white/5 active:bg-white/10 backdrop-blur-[40px] text-[12px] pl-[8px] pr-[16px] py-2 text-white select-none',
    solid: 'bg-white hover:bg-gray-200 active:bg-gray-300 text-black text-[12px] pl-[8px] pr-[16px] py-2 select-none',
  };
  return (
    <button 
      className={`${base} ${variants[variant]} ${className}`} 
      onClick={onClick}
      disabled={disabled}
    >
      {icon && <span className="flex items-center justify-center w-6 h-6">{icon}</span>}
      <span>{children}</span>
    </button>
  );
};

import {StrictMode} from 'react';
import {createRoot} from 'react-dom/client';
import App from './App.tsx';
import './index.css';

createRoot(document.getElementById('root')!).render(
  <StrictMode>
    <App />
  </StrictMode>,
);

import React, { useState, useEffect, useCallback } from 'react';
import { Shot } from './types';
import { ShotTile } from './components/ShotTile';
import { SectionLabel } from './components/UI';
import { Flow } from 'flow-sdk';

const App: React.FC = () => {
  const [globalInstructions, setGlobalInstructions] = useState("");
  const [shots, setShots] = useState<Shot[]>([]);
  const [saveStates, setSaveStates] = useState<Record<string, 'idle' | 'saving' | 'saved'>>({});
  const [draggedId, setDraggedId] = useState<string | null>(null);
  const [dragTargetId, setDragTargetId] = useState<string | null>(null);

  useEffect(() => {
    // Inject Fonts and Icons
    const fontIds = ['gfont-preconnect-1', 'gfont-preconnect-2', 'gfont-link', 'gfont-icons'];
    if (!document.getElementById(fontIds[0])) {
      const pc1 = document.createElement('link');
      pc1.id = fontIds[0]; pc1.rel = 'preconnect'; pc1.href = 'https://fonts.googleapis.com';

      const pc2 = document.createElement('link');
      pc2.id = fontIds[1]; pc2.rel = 'preconnect'; pc2.href = 'https://fonts.gstatic.com';
      (pc2 as any).crossOrigin = '';

      const link = document.createElement('link');
      link.id = fontIds[2]; link.rel = 'stylesheet';
      link.href = 'https://fonts.googleapis.com/css2?family=Google+Sans:wght@400;500;600;700&family=Google+Sans+Flex:wght@400;500;600;700&family=Google+Sans+Text:wght@400;500;600;700&display=swap';

      const icons = document.createElement('link');
      icons.id = fontIds[3]; icons.rel = 'stylesheet';
      icons.href = 'https://fonts.googleapis.com/css2?family=Material+Symbols+Outlined:opsz,wght,FILL,GRAD@24,400,0,0';

      document.head.append(pc1, pc2, link, icons);
    }

    // Inject Design System CSS
    const styleId = 'flow-design-system-css';
    if (!document.getElementById(styleId)) {
      const style = document.createElement('style');
      style.id = styleId;
      style.textContent = `
        @utility scrollbar-hide {
          -ms-overflow-style: none;
          scrollbar-width: none;
          &::-webkit-scrollbar { display: none; }
        }

        .dark-scrollbar { scrollbar-width: thin; scrollbar-color: #595959 transparent; }
        .dark-scrollbar::-webkit-scrollbar { width: 6px; }
        .dark-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .dark-scrollbar::-webkit-scrollbar-thumb { background: #595959; border-radius: 9999px; }
        .dark-scrollbar::-webkit-scrollbar-thumb:hover { background: #7a7a7a; }

        html {
          scrollbar-gutter: stable;
        }

        html, body, #root {
          margin: 0; padding: 0; width: 100%; height: 100%;
          background: #000000;
          font-family: 'Google Sans Text', 'Google Sans', -apple-system, BlinkMacSystemFont, sans-serif;
          letter-spacing: 0.1px;
          -webkit-font-smoothing: antialiased;
          -moz-osx-font-smoothing: grayscale;
          color: white;
        }

        input[type=range] {
          -webkit-appearance: none; appearance: none;
          background: transparent; width: 100%;
          cursor: pointer; padding: 8px 0;
        }
        input[type=range]::-webkit-slider-runnable-track {
          width: 100%; height: 3px;
          background: #595959; border-radius: 9999px;
        }
        input[type=range]::-webkit-slider-thumb {
          -webkit-appearance: none; appearance: none;
          width: 14px; height: 14px; border-radius: 50%;
          background: white; box-shadow: 0px 1px 3px rgba(0,0,0,0.5);
          margin-top: -5.5px; cursor: grab;
        }
        input[type=range]::-webkit-slider-thumb:active { cursor: grabbing; }
      `;
      document.head.appendChild(style);
    }
  }, []);

  const updateShot = useCallback((id: string, updates: Partial<Shot>) => {
    setShots((prev) => prev.map((s) => (s.id === id ? { ...s, ...updates } : s)));
  }, []);

  const performGeneration = useCallback(async (id: string, prompt: string, parentMediaId?: string) => {
    try {
      const basePrompt = parentMediaId 
        ? `Generate an image showing what happens next based on this input: ${prompt}`
        : prompt;

      const finalPrompt = `${basePrompt}. ${globalInstructions}`.trim();

      const result = await Flow.generate.image({
        prompt: finalPrompt,
        aspectRatio: "16:9",
        modelDisplayName: "Nano Banana 2",
        referenceImageMediaIds: parentMediaId ? [parentMediaId] : undefined
      });

      updateShot(id, {
        imageUrl: `data:${result.mimeType};base64,${result.base64}`,
        base64: result.base64,
        mediaId: result.mediaId,
        mimeType: result.mimeType,
        isGenerating: false,
      });
    } catch (error: any) {
      console.error('Generation failed:', error);
      updateShot(id, { isGenerating: false });
      setTimeout(() => alert(`Failed to generate: ${error?.message || 'Unknown error'}`), 100);
    }
  }, [globalInstructions, updateShot]);

  const generateShot = useCallback(async (id: string) => {
    setShots((prevShots) => {
      const shot = prevShots.find((s) => s.id === id);
      if (!shot || !shot.prompt || (shot.imageUrl && shot.mediaId)) return prevShots;

      setTimeout(() => performGeneration(id, shot.prompt, shot.parentMediaId), 0);
      return prevShots.map(s => s.id === id ? { ...s, isGenerating: true } : s);
    });
  }, [performGeneration]);

  const addShot = useCallback(() => {
    setShots((prev) => [
      ...prev,
      {
        id: crypto.randomUUID(),
        prompt: '',
        isGenerating: false,
      },
    ]);
  }, []);

  const followUpShot = useCallback((id: string) => {
    setShots((prev) => {
      const parentIndex = prev.findIndex((s) => s.id === id);
      if (parentIndex === -1) return prev;

      const parent = prev[parentIndex];
      if (!parent.mediaId) return prev;

      const newShot: Shot = {
        id: crypto.randomUUID(),
        prompt: '',
        isGenerating: false,
        parentMediaId: parent.mediaId,
        imageUrl: parent.imageUrl,
        placeholder: 'Describe what happens next...'
      };

      const newShots = [...prev];
      newShots.splice(parentIndex + 1, 0, newShot);
      return newShots;
    });
  }, []);

  const deleteShot = useCallback((id: string) => {
    setShots((prev) => prev.filter((s) => s.id !== id));
  }, []);

  const saveShot = useCallback(async (id: string) => {
    const shot = shots.find((s) => s.id === id);
    if (!shot?.base64 || !shot?.mimeType) return;

    setSaveStates(prev => ({ ...prev, [id]: 'saving' }));
    try {
      await Flow.save({
        base64: shot.base64,
        mimeType: shot.mimeType as any,
        name: shot.prompt.slice(0, 30) || 'Story Sketch'
      });
      setSaveStates(prev => ({ ...prev, [id]: 'saved' }));
      setTimeout(() => {
        setSaveStates(prev => ({ ...prev, [id]: 'idle' }));
      }, 2000);
    } catch (error) {
      console.error('Save failed:', error);
      setSaveStates(prev => ({ ...prev, [id]: 'idle' }));
    }
  }, [shots]);

  const resetAllImages = useCallback(() => {
    setShots([]);
  }, []);

  const handleDragStart = (e: React.DragEvent, id: string) => {
    setDraggedId(id);
    e.dataTransfer.setData('text/plain', id);
    e.dataTransfer.effectAllowed = 'move';
  };

  const handleDragOver = (e: React.DragEvent, id: string) => {
    e.preventDefault();
    if (draggedId !== id) {
      setDragTargetId(id);
    }
  };

  const handleDragEnd = () => {
    if (draggedId && dragTargetId && draggedId !== dragTargetId) {
      setShots((prev) => {
        const oldIndex = prev.findIndex((s) => s.id === draggedId);
        const newIndex = prev.findIndex((s) => s.id === dragTargetId);
        const newShots = [...prev];
        const [removed] = newShots.splice(oldIndex, 1);
        newShots.splice(newIndex, 0, removed);
        return newShots;
      });
    }
    setDraggedId(null);
    setDragTargetId(null);
  };

  return (
    <div className="min-h-screen bg-black text-white selection:bg-white selection:text-black">
      <div className="max-w-[1600px] mx-auto px-6 py-6 lg:px-10 lg:py-10">

        <div className="mb-[24px] flex flex-col gap-1.5">
          <div className="flex justify-between items-center h-8 pr-2">
            <SectionLabel>Instructions</SectionLabel>
            <button 
              onClick={resetAllImages}
              disabled={shots.length === 0}
              className={`flex items-center gap-1.5 transition-all py-1 group ${
                shots.length === 0 
                  ? 'opacity-0 pointer-events-none' 
                  : 'text-[rgba(218,220,224,0.55)] hover:text-red-400 opacity-100 cursor-pointer'
              }`}
              title="Clear All Shots"
            >
              <span className="text-[11px] font-medium tracking-[0.1px]">
                Reset
              </span>
              <span className="material-symbols-outlined text-[18px] group-hover:rotate-[-90deg] transition-transform">restart_alt</span>
            </button>
          </div>
          <textarea
            value={globalInstructions}
            onChange={(e) => setGlobalInstructions(e.target.value)}
            placeholder="Set the visual style (e.g. cinematic, warm lighting) ..."
            className="w-full bg-black border border-[#595959] hover:border-[#7a7a7a] focus:border-[#969696] p-[12px] text-[13px] font-medium leading-relaxed focus:outline-none transition-colors min-h-[100px] resize-none placeholder:text-[rgba(255,255,255,0.35)] rounded-xl tracking-[0.1px]"
          />
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-[24px]">
          {shots.map((shot) => (
            <ShotTile
              key={shot.id}
              shot={shot}
              isDragging={draggedId === shot.id}
              isDragTarget={dragTargetId === shot.id}
              showGrip={shots.length > 1}
              onUpdate={updateShot}
              onGenerate={generateShot}
              onDelete={deleteShot}
              onSave={saveShot}
              saveState={saveStates[shot.id] || 'idle'}
              onFollowUp={followUpShot}
              onDragStart={handleDragStart}
              onDragOver={handleDragOver}
              onDragEnd={handleDragEnd}
            />
          ))}

          <button
            onClick={addShot}
            className="aspect-video w-full border border-dashed border-[#595959] hover:border-[#7a7a7a] hover:bg-white/5 transition-all flex flex-col items-center justify-center gap-2 group rounded-xl bg-transparent"
          >
            <div className="w-10 h-10 rounded-full border border-[#595959] flex items-center justify-center group-hover:border-[#7a7a7a] group-hover:scale-110 transition-all">
              <span className="material-symbols-outlined text-[24px] text-white">add</span>
            </div>
            <span className="text-[11px] font-medium tracking-[0.1px] text-[rgba(218,220,224,0.9)]">
              Add shot
            </span>
          </button>
        </div>
      </div>
    </div>
  );
};

export default App;
